from itertools import combinations

def solve_game(n):
    memo = {}

    def get_result(current_player, chosen, alice_set, bob_set):
        state = (current_player, tuple(sorted(list(chosen))), tuple(sorted(list(alice_set))), tuple(sorted(list(bob_set))))
        if state in memo:
            return memo[state]

        # Check if all numbers are chosen
        if len(chosen) == n:
            return 0  # Draw

        # Possible moves for current_player
        possible_moves = []
        player_set = alice_set if current_player == 0 else bob_set
        for x in range(1, n + 1):
            if x not in chosen:
                # Check if consecutive to any of player's previous choices
                if not ((x - 1 in player_set) or (x + 1 in player_set)):
                    possible_moves.append(x)

        if not possible_moves:
            # Current player loses
            return -1 if current_player == 0 else 1

        results = []
        for move in possible_moves:
            new_chosen = chosen | {move}
            new_alice = alice_set | {move} if current_player == 0 else alice_set
            new_bob = bob_set | {move} if current_player == 1 else bob_set
            res = get_result(1 - current_player, new_chosen, new_alice, new_bob)
            results.append(res)

        if current_player == 0:
            # Alice wants to maximize
            final_res = max(results)
        else:
            # Bob wants to minimize
            final_res = min(results)

        memo[state] = final_res
        return final_res

    return get_result(0, set(), set(), set())

